:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle, #2a2a4a 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border);
}

h1 {
  margin: 0 0 24px;
  font-size: 1.75rem;
  text-align: center;
  letter-spacing: 2px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.field { margin-bottom: 20px; }

label, .label {
  display: block;
  margin-bottom: 8px;
  font-size: 1rem;
  color: var(--muted);
}

input {
  width: 100%;
  padding: 12px;
  font-size: 1.125rem;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  outline: none;
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.tip-buttons {
  display: flex;
  gap: 10px;
}

.tip-btn {
  flex: 1;
  padding: 12px 0;
  font-size: 1rem;
  font-family: var(--font);
  font-weight: bold;
  cursor: pointer;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  transition: background 0.1s, transform 0.05s;
}

.tip-btn:hover {
  background: #2a2a4a;
  border-color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(2px, 2px);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--card);
  border-color: var(--accent);
}

.results {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 3px dashed var(--border);
}

.result-row {
  display: flex;
  justify-content: space-between;
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.result-row.total {
  font-size: 1.375rem;
  font-weight: bold;
  color: var(--accent);
  margin-bottom: 0;
}

@media (max-width: 400px) {
  .card { padding: 16px; box-shadow: 4px 4px 0 var(--border); }
  h1 { font-size: 1.5rem; }
  .tip-buttons { gap: 6px; }
  .tip-btn { padding: 10px 0; font-size: 0.9375rem; }
}

const billInput = document.getElementById('bill');
const peopleInput = document.getElementById('people');
const tipButtons = document.querySelectorAll('.tip-btn');
const tipAmountEl = document.getElementById('tip-amount');
const totalPerPersonEl = document.getElementById('total-per-person');

let currentTip = 15;

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function calculate() {
  const bill = parseFloat(billInput.value);
  const people = parseInt(peopleInput.value, 10);

  if (isNaN(bill) || bill < 0 || isNaN(people) || people < 1) {
    tipAmountEl.textContent = '$0.00';
    totalPerPersonEl.textContent = '$0.00';
    return;
  }

  const tip = bill * (currentTip / 100);
  const total = bill + tip;
  const perPerson = total / people;

  tipAmountEl.textContent = formatCurrency(tip);
  totalPerPersonEl.textContent = formatCurrency(perPerson);
}

function selectTip(percent) {
  currentTip = percent;
  tipButtons.forEach(btn => {
    const isActive = parseInt(btn.dataset.tip, 10) === percent;
    btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
  });
  calculate();
}

tipButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    selectTip(parseInt(btn.dataset.tip, 10));
  });
});

billInput.addEventListener('input', calculate);
peopleInput.addEventListener('input', calculate);

calculate();
